import os
import requests
from dotenv import load_dotenv

# Load environment variables from .env file
load_dotenv()

# Read API key from environment
API_KEY = os.getenv("GROQ_API_KEY")

# Groq OpenAI-compatible endpoint
URL = "https://api.groq.com/openai/v1/chat/completions"


# Function to call the LLM API with a given prompt
# Returns the text response generated by the model
#
# Currently used for topic extraction,
# but designed to be reusable for other LLM tasks

def call_llm(prompt: str, model: str = "llama-3.1-8b-instant", temperature: float = 0.2) -> str:

    # Ensure API key exists
    if not API_KEY:
        raise ValueError("GROQ_API_KEY not found")

    # Build request payload
    # messages format follows OpenAI chat API format
    payload = {  # type: ignore
        "model": model,
        "temperature": temperature,
        "messages": [
            {"role": "user", "content": prompt}
        ]
    }

    # HTTP request headers
    headers = {
        "Authorization": f"Bearer {API_KEY}",
        "Content-Type": "application/json"
    }

    # Send POST request to the Groq API
    response = requests.post(URL, headers=headers, json=payload, timeout=30)  # type: ignore

    # Raise error if request failed (4xx / 5xx)
    response.raise_for_status()

    # Convert response JSON into Python dict
    result = response.json()

    # Validate response structure
    if "choices" not in result or not result["choices"]:
        raise ValueError(f"Unexpected API response: {result}")

    # Extract model output text
    return result["choices"][0]["message"]["content"].strip()  # type: ignore